<template><section class="photo-editor"><header><h2>프로필 사진</h2><span>{{images.length}} / 6</span></header><p class="photo-help">사진을 눌러 교체하고, 대표로 사용할 사진을 선택하세요.</p><div class="photo-grid"><div v-for="(item,i) in slots" :key="i" class="photo-cell"><template v-if="item"><button type="button" class="photo-pick" :disabled="busy" :aria-label="`${i+1}번 사진 교체`" @click="pick(item)"><img :src="url(item.imageUrl)" alt="내 프로필 사진"/></button><button type="button" class="photo-remove" :disabled="busy" :aria-label="`${i+1}번 사진 삭제`" @click="remove(item)">×</button><button type="button" :class="['photo-main',{selected:item.isMain}]" :disabled="busy" @click="main(item)">{{item.isMain?'대표사진':'대표로 설정'}}</button></template><button v-else type="button" class="photo-add" :disabled="busy" :aria-label="`${i+1}번 사진 추가`" @click="pick(null)"><span>＋</span>사진 추가</button></div></div><input ref="input" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden @change="choose"/><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">사진 저장 중…</p><p v-if="message" role="status">{{message}}</p><p class="photo-help">승인 회원의 사진 변경은 재심사 후 공개됩니다.<br/>최대 6장 · JPG, PNG, WebP · 사진당 10MB<br/>내가 등록한 사진 수만큼 상대 사진을 볼 수 있어요.</p>
<dialog ref="crop" class="social-dialog crop-dialog" @cancel="cancelCrop"><header><h2>사진 자르기</h2><button type="button" :disabled="busy" aria-label="자르기 취소" @click="cancelCrop">×</button></header><p>사진을 드래그해 위치를 맞춰 주세요.</p><canvas ref="canvas" width="600" height="600" @pointerdown="startDrag" @pointermove="drag" @pointerup="endDrag" @pointercancel="endDrag"/><label>확대<input type="range" min="1" max="3" step="0.01" v-model.number="zoom" @input="draw"/></label><button type="button" class="primary" :disabled="busy" @click="save">{{busy?'저장 중…':'이 사진 사용'}}</button><p v-if="cropError" role="alert">{{cropError}}</p></dialog></section></template>
<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';import api from '../api/api';import './social.css';
const emit=defineEmits(['changed']),images=ref([]),input=ref(),crop=ref(),canvas=ref(),error=ref(''),cropError=ref(''),message=ref(''),busy=ref(false),zoom=ref(1);
const slots=computed(()=>Array.from({length:6},(_,i)=>images.value[i]||null)),url=p=>new URL(p,api.defaults.baseURL).href;let queue=[],target=null,source=null,bitmap=null,x=0,y=0,dragging=null,disposed=false;
async function load(){busy.value=true;try{images.value=(await api.get('/profile-images/me')).data;emit('changed',images.value);}catch{error.value='사진을 불러오지 못했어요.';}finally{busy.value=false;}}
function pick(item){target=item;input.value.multiple=!item;input.value.click();}
async function choose(e){queue=[...e.target.files];e.target.value='';error.value='';message.value='';if(queue.length>(target?1:6-images.value.length)){error.value='사진은 최대 6장까지 등록할 수 있어요.';queue=[];return;}await next();}
async function next(){if(source)URL.revokeObjectURL(source);if(!queue.length){crop.value.close();return;}const file=queue.shift();if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){error.value='JPG, PNG, WebP 형식의 10MB 이하 사진을 선택해 주세요.';queue=[];crop.value.close();return;}source=URL.createObjectURL(file);bitmap=new Image();try{bitmap.src=source;await bitmap.decode();if(disposed)return;zoom.value=1;x=y=0;cropError.value='';if(!crop.value.open)crop.value.showModal();await nextTick();draw();}catch{error.value='사진을 읽을 수 없습니다. 다른 사진을 선택해 주세요.';queue=[];crop.value.close();}}
function geometry(){const scale=Math.max(600/bitmap.width,600/bitmap.height)*zoom.value;const w=bitmap.width*scale,h=bitmap.height*scale;x=Math.max(-(w-600)/2,Math.min((w-600)/2,x));y=Math.max(-(h-600)/2,Math.min((h-600)/2,y));return{w,h,left:(600-w)/2+x,top:(600-h)/2+y};}
function draw(){if(!bitmap||!canvas.value)return;const g=geometry(),ctx=canvas.value.getContext('2d');ctx.clearRect(0,0,600,600);ctx.drawImage(bitmap,g.left,g.top,g.w,g.h);}
function startDrag(e){if(busy.value)return;dragging={x:e.clientX,y:e.clientY};canvas.value.setPointerCapture(e.pointerId);}
function drag(e){if(!dragging||busy.value)return;const ratio=600/canvas.value.clientWidth;x+=(e.clientX-dragging.x)*ratio;y+=(e.clientY-dragging.y)*ratio;dragging={x:e.clientX,y:e.clientY};draw();}function endDrag(){dragging=null;}
function cancelCrop(e){if(busy.value){e?.preventDefault?.();return;}queue=[];crop.value.close();if(source){URL.revokeObjectURL(source);source=null;}}
async function save(){if(busy.value)return;busy.value=true;cropError.value='';try{const blob=await new Promise(resolve=>canvas.value.toBlob(resolve,'image/jpeg',.9));if(!blob)throw Error();const order=target?.imageOrder??[1,2,3,4,5,6].find(n=>!images.value.some(i=>i.imageOrder===n));const form=new FormData();form.append('file',blob,'profile.jpg');form.append('imageOrder',String(order));form.append('isMain',String(target?.isMain||!images.value.length));images.value=(await api.post('/profile-images/me/upload',form,{headers:{'Content-Type':'multipart/form-data'}})).data;emit('changed',images.value);message.value='사진을 저장했어요. 승인 회원의 변경 내용은 재심사 후 공개됩니다.';target=null;await next();}catch(e){cropError.value=e.response?.data?.message||'저장하지 못했어요. 다시 시도해 주세요.';}finally{busy.value=false;}}
async function remove(item){if(busy.value)return;busy.value=true;error.value='';try{images.value=(await api.delete(`/profile-images/me/${item.id}`)).data;emit('changed',images.value);message.value='사진을 삭제했어요.';}catch(e){error.value=e.response?.data?.message||'삭제하지 못했어요.';}finally{busy.value=false;}}
async function main(item){if(busy.value||item.isMain)return;busy.value=true;error.value='';try{images.value=(await api.put(`/profile-images/me/${item.id}/main`)).data;emit('changed',images.value);message.value='대표사진을 변경했어요.';}catch{error.value='대표사진을 바꾸지 못했어요.';}finally{busy.value=false;}}
onMounted(load);onUnmounted(()=>{disposed=true;if(source)URL.revokeObjectURL(source);});
</script><style scoped>.photo-editor{background:#fff;padding:20px;border-radius:20px;color:#302925}.photo-editor header{display:flex;justify-content:space-between;align-items:center}.photo-editor h2{font-size:17px;margin:0}.photo-editor header span{font-size:12px;color:#a29289}.photo-help{font-size:12px;line-height:1.7;color:#8f8178}.photo-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin:18px 0}.photo-cell{position:relative;aspect-ratio:3/4;border-radius:13px;overflow:hidden;background:#f7f4f1}.photo-cell button{border:0;cursor:pointer;font:inherit}.photo-pick{padding:0;width:100%;height:100%;display:block}.photo-pick img{width:100%;height:100%;object-fit:cover}.photo-remove{padding:0!important;line-height:28px;position:absolute;right:5px;top:5px;width:28px;height:28px;border-radius:50%;background:rgba(0,0,0,.5);color:#fff;font-size:20px!important}.photo-main{position:absolute;bottom:0;left:0;width:100%;padding:8px 2px;background:rgba(0,0,0,.4);color:#fff;font-size:10px!important}.photo-main.selected{background:#d56f4e}.photo-add{width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;background:transparent;color:#ac9180;font-size:11px!important}.photo-add span{font-size:30px}.crop-dialog canvas{width:100%;height:auto;display:block;touch-action:none;border-radius:12px}.crop-dialog input{width:100%;accent-color:#d56f4e}.photo-editor [role=alert]{color:#ac3c2c;font-size:13px}.photo-editor [role=status]{font-size:12px}.photo-editor button:disabled{opacity:.5}</style>
